const { total, budget, remaining, cadence } = $input.first().json;
const over = Math.abs(remaining).toFixed(2);
const text = `\u26A0\uFE0F Household Ledger: $${total.toFixed(2)} of your $${budget.toFixed(2)} ${String(cadence || '').toLowerCase()} budget spent \u2014 $${over} over.`;
return [{ json: { text } }];
